def interactive_feedback(project_directory, summary, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0325000" if __import__("os").path.isdir("./environment_mix/0325000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _canonicalize_path(p):
        if not isinstance(p, str):
            return None
        s = p.strip()
        if s == "":
            return ""
        try:
            s2 = os.path.expanduser(s)
            # Normalize separators and collapse .. and .
            s2 = os.path.normpath(s2)
            # Make absolute when possible (do not require path to exist)
            if not os.path.isabs(s2):
                s2 = os.path.abspath(s2)
            # Try resolving symlinks when possible
            try:
                s2 = os.path.realpath(s2)
            except Exception:
                pass
            # Normalize case on Windows-like envs
            try:
                s2 = os.path.normcase(s2)
            except Exception:
                pass
            return s2
        except Exception:
            return None

    def _gen_id(prefix):
        # deterministic enough for offline store
        import secrets
        return f"{prefix}_{datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(8)}"

    def _audit(endpoint, status, credential=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("reqlog"),
            "endpoint": endpoint,
            "credential": credential,
            "status": status,
            "error_code": error_code,
            "timestamp": _now(),
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    _t0 = time.time()
    endpoint = "interactive_feedback"

    # Input validation
    if not isinstance(project_directory, str):
        _audit(endpoint, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_directory must be a string.")
    if not isinstance(summary, str):
        _audit(endpoint, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "summary must be a string.")
    if project_directory.strip() == "":
        _audit(endpoint, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_directory must be non-empty.")
    if summary.strip() == "":
        _audit(endpoint, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "summary must be non-empty.")
    if len(summary) > 280:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "summary must be <= 280 characters.", max_length=280)

    canonical = _canonicalize_path(project_directory)
    if canonical is None:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_directory could not be canonicalized.")
    if canonical == "":
        _audit(endpoint, "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_directory_canonical must be non-empty after canonicalization.")

    # Load collections
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    requests = _load("feedback_requests.json")
    if not isinstance(requests, list):
        requests = []
    snapshots = _load("project_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []
    prompts = _load("feedback_prompts.json")
    if not isinstance(prompts, list):
        prompts = []
    responses = _load("feedback_responses.json")
    if not isinstance(responses, list):
        responses = []

    now = _now()

    # Find or create project by directory_path_canonical (unique)
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("directory_path_canonical") == canonical:
            proj = p
            break

    if proj is None:
        proj = {
            "id": _gen_id("proj"),
            "directory_path": project_directory,
            "directory_path_canonical": canonical,
            "display_name": os.path.basename(canonical) or None,
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
            "status": "active",
        }
        projects.append(proj)
    else:
        # Ensure lifecycle field exists
        if proj.get("status") not in ("active", "archived"):
            proj["status"] = "active"
        proj["last_seen_at"] = now
        proj["updated_at"] = now
        # Keep original directory_path as last provided for traceability
        proj["directory_path"] = project_directory

    # Create feedback request (no client_request_id on tool surface)
    fr = {
        "id": _gen_id("fbr"),
        "project_id": proj["id"],
        "project_directory": project_directory,
        "summary": summary,
        "request_source": "mcp_tool",
        "client_request_id": None,
        "opened_at": None,
        "closed_at": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "status": "queued",
    }
    requests.append(fr)

    # Snapshot basic project metadata (must be unique per feedback_request_id)
    # Enforce: only when queued or active (new request is queued)
    # Gather file list (best-effort; if directory missing, snapshot empty but valid)
    files_list = []
    file_count = 0
    git_repo_root = None
    git_head_ref = None
    git_head_sha = None

    try:
        # Determine git info via .git if present
        # Search upwards from canonical until filesystem root; stop when .git found
        cur = canonical
        while True:
            git_dir = os.path.join(cur, ".git")
            if os.path.isdir(git_dir):
                git_repo_root = cur
                head_path = os.path.join(git_dir, "HEAD")
                try:
                    with open(head_path, encoding="utf-8") as f:
                        head = f.read().strip()
                    if head.startswith("ref:"):
                        ref = head.split(":", 1)[1].strip()
                        git_head_ref = ref
                        ref_path = os.path.join(git_dir, ref.replace("/", os.sep))
                        if os.path.exists(ref_path):
                            with open(ref_path, encoding="utf-8") as rf:
                                git_head_sha = rf.read().strip() or None
                    else:
                        git_head_sha = head or None
                except Exception:
                    pass
                break
            parent = os.path.dirname(cur)
            if parent == cur:
                break
            cur = parent
    except Exception:
        pass

    try:
        if os.path.isdir(canonical):
            # Avoid gigantic snapshots: include at most 5000 files, skip hidden dirs and .git
            max_files = 5000
            for root, dirs, filenames in os.walk(canonical):
                # prune dirs
                pruned = []
                for d in list(dirs):
                    if d == ".git" or d.startswith("."):
                        pruned.append(d)
                for d in pruned:
                    if d in dirs:
                        dirs.remove(d)
                for fn in filenames:
                    if fn.startswith("."):
                        continue
                    full = os.path.join(root, fn)
                    rel = os.path.relpath(full, canonical)
                    files_list.append(rel.replace(os.sep, "/"))
                    if len(files_list) >= max_files:
                        break
                if len(files_list) >= max_files:
                    break
            file_count = len(files_list)
        else:
            files_list = []
            file_count = 0
    except Exception:
        # If walking fails, still capture empty snapshot
        files_list = []
        file_count = 0

    # Ensure uniqueness: none exists for this request id (it won't)
    snap = {
        "id": _gen_id("snap"),
        "feedback_request_id": fr["id"],
        "directory_path_canonical": canonical,
        "git_repo_root": git_repo_root,
        "git_head_ref": git_head_ref,
        "git_head_sha": git_head_sha,
        "file_count": int(file_count),
        "files": files_list,
        "created_at": now,
        "updated_at": now,
        "status": "captured",
    }
    snapshots.append(snap)

    # Persist all
    _save("projects.json", projects)
    _save("feedback_requests.json", requests)
    _save("project_snapshots.json", snapshots)
    # prompts/responses unchanged but ensure files exist? no need.

    body = {
        "request": fr,
        "project": proj,
        "snapshot": snap,
    }
    _audit(endpoint, "ok")
    return body

def interactive_feedback_me(auth_token, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0325000" if __import__("os").path.isdir("./environment_mix/0325000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _audit(endpoint, status, credential=None, error_code=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started_at is not None:
            latency_ms = int((time.time() - started_at) * 1000)
        logs.append(
            {
                "id": "ifp_rlg_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential": credential,
                "status": status,
                "error_code": error_code,
                "timestamp": _now_iso(),
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "interactive_feedback_me"

    if not isinstance(auth_token, str) or not auth_token.strip():
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "auth_token must be a non-empty string.")

    # The datastore for this service has no explicit credential collection in the schema.
    # Real behaviour: accept any non-empty token as an authenticated caller and report usage/rate status.
    # (Do NOT attempt to match against non-existent or hashed credentials.)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []

    now = datetime.datetime.now(datetime.timezone.utc)
    window_60s = now - datetime.timedelta(seconds=60)
    window_1h = now - datetime.timedelta(hours=1)

    last_60s = 0
    last_1h = 0
    total = 0
    by_endpoint = {}

    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential") != auth_token:
            continue
        ts = _parse_dt(r.get("timestamp") or r.get("created_at"))
        if ts is None:
            continue
        total += 1
        ep = r.get("endpoint") or "unknown"
        by_endpoint[ep] = by_endpoint.get(ep, 0) + 1
        if ts >= window_60s:
            last_60s += 1
        if ts >= window_1h:
            last_1h += 1

    # Soft rate guidance (no schema-defined hard limits for this service)
    rate = {
        "last_60s": last_60s,
        "last_1h": last_1h,
        "limits": None,
    }

    body = {
        "identity": {
            "type": "bearer_token",
            "token_id": auth_token,
        },
        "scopes": ["interactive_feedback:read", "interactive_feedback:write"],
        "usage": {
            "total_requests": total,
            "requests_by_endpoint": by_endpoint,
        },
        "rate_limit": rate,
    }

    _audit(endpoint, "success", credential=auth_token, started_at=t0)
    return body

def interactive_feedback_requests_list(auth_token, project_id=None, project_directory=None, status=None, client_request_id=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0325000" if __import__("os").path.isdir("./environment_mix/0325000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt_required(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return ("error", _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string."))
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return ("error", _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string."))

    def _audit(endpoint, status_s, credential=None, error_code=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started_at is not None:
            latency_ms = int((time.time() - started_at) * 1000)
        logs.append(
            {
                "id": "ifp_rlg_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential": credential,
                "status": status_s,
                "error_code": error_code,
                "timestamp": _now_iso(),
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "interactive_feedback_requests_list"

    if not isinstance(auth_token, str) or auth_token.strip() == "":
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "auth_token must be a non-empty string.")

    # No credential datastore: accept any non-empty token as authenticated for this local service.
    if project_id is not None and (not isinstance(project_id, str) or not project_id.strip()):
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string when provided.")
    if project_directory is not None and (not isinstance(project_directory, str) or not project_directory.strip()):
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "project_directory must be a non-empty string when provided.")
    if client_request_id is not None and (not isinstance(client_request_id, str) or not client_request_id.strip()):
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "client_request_id must be a non-empty string when provided.")

    allowed_status = {"queued", "active", "awaiting_user", "completed", "cancelled", "errored"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
            return _err("VALIDATION_ERROR", "status must be one of queued, active, awaiting_user, completed, cancelled, errored.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    ca = _parse_dt_required(created_after, "created_after")
    if isinstance(ca, tuple) and ca and ca[0] == "error":
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return ca[1]
    cb = _parse_dt_required(created_before, "created_before")
    if isinstance(cb, tuple) and cb and cb[0] == "error":
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return cb[1]

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    projects_by_id = {p.get("id"): p for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}

    requests = _load("feedback_requests.json")
    if not isinstance(requests, list):
        requests = []

    def _parse_created(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        ss = s
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # Filter
    out = []
    for r in requests:
        if not isinstance(r, dict):
            continue
        rid = r.get("id")
        if not isinstance(rid, str):
            continue

        if project_id is not None and r.get("project_id") != project_id:
            continue
        if project_directory is not None and r.get("project_directory") != project_directory:
            continue
        if status is not None and r.get("status") != status:
            continue
        if client_request_id is not None and r.get("client_request_id") != client_request_id:
            continue

        # enforce FK visibility/integrity: only list rows whose project exists
        pid = r.get("project_id")
        if not isinstance(pid, str) or pid not in projects_by_id:
            continue

        created_dt = _parse_created(r)
        if ca is not None:
            if created_dt is None or created_dt < ca:
                continue
        if cb is not None:
            if created_dt is None or created_dt > cb:
                continue

        out.append(r)

    # Sort: created_at desc (fallback updated_at desc, then id)
    def _sort_key(r):
        cd = _parse_created(r) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        ud = None
        us = r.get("updated_at")
        if isinstance(us, str):
            ss = us
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            try:
                ud = datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
            except Exception:
                ud = None
        if ud is None:
            ud = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (cd, ud, r.get("id") or "")

    out.sort(key=_sort_key, reverse=True)

    # Pagination: cursor is an opaque "start after id"
    start_index = 0
    if cursor is not None:
        for i, r in enumerate(out):
            if r.get("id") == cursor:
                start_index = i + 1
                break

    page = out[start_index : start_index + limit]
    has_more = start_index + limit < len(out)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    resp = {
        "data": page,
        "meta": {
            "total": len(out),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
    _audit(endpoint, "success", credential=auth_token, started_at=t0)
    return resp

def interactive_feedback_request_get(auth_token, feedback_request_id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0325000" if __import__("os").path.isdir("./environment_mix/0325000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _audit(endpoint, status_s, credential=None, error_code=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started_at is not None:
            latency_ms = int((time.time() - started_at) * 1000)
        logs.append(
            {
                "id": "ifp_rlg_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential": credential,
                "status": status_s,
                "error_code": error_code,
                "timestamp": _now_iso(),
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "interactive_feedback_request_get"

    if not isinstance(auth_token, str) or auth_token.strip() == "":
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "auth_token must be a non-empty string.")
    if not isinstance(feedback_request_id, str) or feedback_request_id.strip() == "":
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "feedback_request_id must be a non-empty string.")

    # No credential datastore: accept any non-empty token as authenticated.

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project_ids = {p.get("id") for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}

    reqs = _load("feedback_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    found = None
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == feedback_request_id:
            # enforce FK integrity/visibility
            pid = r.get("project_id")
            if isinstance(pid, str) and pid in project_ids:
                found = r
            break

    if found is None:
        _audit(endpoint, "error", credential=auth_token, error_code="NOT_FOUND", started_at=t0)
        return _err("NOT_FOUND", "Feedback request not found.")

    _audit(endpoint, "success", credential=auth_token, started_at=t0)
    return {"data": found}

def interactive_feedback_request_update(auth_token, feedback_request_id, status=None, error_message=None, opened_at=None, closed_at=None, **_extra):
