        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return ("error", _err("VALIDATION_ERROR", f"{field} must be an ISO date-time string."))
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return ("error", _err("VALIDATION_ERROR", f"{field} must be a valid ISO date-time string."))

    def _audit(endpoint, status_s, credential=None, error_code=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started_at is not None:
            latency_ms = int((time.time() - started_at) * 1000)
        logs.append(
            {
                "id": "ifp_rlg_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential": credential,
                "status": status_s,
                "error_code": error_code,
                "timestamp": _now_iso(),
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "interactive_feedback_request_update"

    if not isinstance(auth_token, str) or not auth_token.strip():
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "auth_token must be a non-empty string.")
    if not isinstance(feedback_request_id, str) or not feedback_request_id.strip():
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return _err("VALIDATION_ERROR", "feedback_request_id must be a non-empty string.")

    allowed_status = {"queued", "active", "awaiting_user", "completed", "cancelled", "errored"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
            return _err("VALIDATION_ERROR", "status must be one of queued, active, awaiting_user, completed, cancelled, errored.")

    if error_message is not None:
        if not isinstance(error_message, str):
            _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
            return _err("VALIDATION_ERROR", "error_message must be a string.")
        if len(error_message) > 2000:
            _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
            return _err("VALIDATION_ERROR", "error_message must be at most 2000 characters.")

    po = _parse_dt(opened_at, "opened_at")
    if isinstance(po, tuple) and po and po[0] == "error":
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return po[1]
    pc = _parse_dt(closed_at, "closed_at")
    if isinstance(pc, tuple) and pc and pc[0] == "error":
        _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
        return pc[1]

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    project_ids = {p.get("id") for p in projects if isinstance(p, dict) and isinstance(p.get("id"), str)}

    reqs = _load("feedback_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    idx = None
    req = None
    for i, r in enumerate(reqs):
        if isinstance(r, dict) and r.get("id") == feedback_request_id:
            pid = r.get("project_id")
            if isinstance(pid, str) and pid in project_ids:
                idx = i
                req = r
            break

    if req is None:
        _audit(endpoint, "error", credential=auth_token, error_code="NOT_FOUND", started_at=t0)
        return _err("NOT_FOUND", "Feedback request not found.")

    current_status = req.get("status")
    if not isinstance(current_status, str):
        current_status = "queued"

    transitions = {
        "queued": {"active", "cancelled", "errored"},
        "active": {"awaiting_user", "completed", "cancelled", "errored"},
        "awaiting_user": {"active", "completed", "cancelled", "errored"},
        "completed": set(),
        "cancelled": set(),
        "errored": set(),
    }

    # If caller requests the same status, treat as idempotent no-op (allowed).
    changing_status = status is not None and status != current_status

    if changing_status:
        allowed_next = transitions.get(current_status, set())
        if status not in allowed_next:
            _audit(endpoint, "error", credential=auth_token, error_code="INVALID_TRANSITION", started_at=t0)
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=current_status, to_status=status)

        # Completing: ensure required prompts are answered (prompt status answered OR has recorded response)
        if status == "completed":
            prompts = _load("feedback_prompts.json")
            if not isinstance(prompts, list):
                prompts = []
            responses = _load("feedback_responses.json")
            if not isinstance(responses, list):
                responses = []
            responses_by_prompt = {}
            for rsp in responses:
                if isinstance(rsp, dict) and isinstance(rsp.get("prompt_id"), str):
                    responses_by_prompt[rsp["prompt_id"]] = rsp

            missing = []
            for p in prompts:
                if not isinstance(p, dict):
                    continue
                if p.get("feedback_request_id") != feedback_request_id:
                    continue
                if p.get("is_required") is True:
                    pid = p.get("id")
                    pstatus = p.get("status")
                    has_recorded = False
                    if isinstance(pid, str) and pid in responses_by_prompt:
                        rr = responses_by_prompt[pid]
                        has_recorded = (rr.get("status") == "recorded")
                    if pstatus != "answered" and not has_recorded:
                        missing.append(pid or "(unknown_prompt_id)")
            if missing:
                _audit(endpoint, "error", credential=auth_token, error_code="VALIDATION_ERROR", started_at=t0)
                return _err(
                    "VALIDATION_ERROR",
                    "Cannot complete request: required prompts unanswered.",
                    missing_required_prompt_ids=missing,
                )

    now_iso = _now_iso()
    # Apply field updates
    req["updated_at"] = now_iso

    # opened_at: server may overwrite on activation; accept provided but normalize.
    if po is not None and not (isinstance(po, tuple) and po and po[0] == "error"):
        req["opened_at"] = po.isoformat().replace("+00:00", "Z")

    # status changes and derived fields
    if changing_status:
        req["status"] = status
        if status == "active":
            req["opened_at"] = now_iso
            # do not set closed_at
            req["closed_at"] = None
            req["error_message"] = None
        elif status == "awaiting_user":
            # keep opened_at as-is if present
            req["error_message"] = None
        elif status == "errored":
            req["error_message"] = error_message if isinstance(error_message, str) and error_message.strip() else (req.get("error_message") or "Unknown error.")
            req["closed_at"] = now_iso
        elif status == "cancelled":
            req["error_message"] = None
            req["closed_at"] = now_iso
        elif status == "completed":
            req["error_message"] = None
            req["closed_at"] = now_iso

    # closed_at: ignore client-provided closed_at unless request is being closed now; but allow idempotent re-send
    # when already closed.
    if pc is not None and not (isinstance(pc, tuple) and pc and pc[0] == "error"):
        # Only accept if request is already in a terminal state
        terminal = req.get("status") in ("completed", "cancelled", "errored")
        if terminal:
            req["closed_at"] = pc.isoformat().replace("+00:00", "Z")

    # error_message: allow setting only when status is errored (or already errored)
    if error_message is not None:
        if req.get("status") == "errored":
            req["error_message"] = error_message
        # otherwise ignore per tool description

    # Persist mutation
    reqs[idx] = req
    _save("feedback_requests.json", reqs)

    _audit(endpoint, "success", credential=auth_token, started_at=t0)
    return {"data": req}

def interactive_feedback_request_prompts_upsert(auth_token, feedback_request_id, prompts, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0325000" if __import__("os").path.isdir("./environment_mix/0325000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, token_used, status_out, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "rl_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "auth_token": token_used,
            "status": status_out,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    if not isinstance(auth_token, str) or not auth_token.strip():
        _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid auth_token.")
    if not isinstance(feedback_request_id, str) or not feedback_request_id.strip():
        _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "feedback_request_id must be a non-empty string.")
    if not isinstance(prompts, list) or len(prompts) < 1:
        _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prompts must be a non-empty array.")

    reqs = _load("feedback_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req = None
    for row in reqs:
        if isinstance(row, dict) and row.get("id") == feedback_request_id:
            req = row
            break
    if req is None:
        _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Feedback request not found.", feedback_request_id=feedback_request_id)

    if req.get("status") in ("completed", "cancelled", "errored"):
        _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Cannot upsert prompts for a terminal feedback request.", status=req.get("status"))

    # Validate prompts payload
    allowed_prompt_types = {"text", "single_choice", "multi_choice", "boolean"}
    allowed_statuses = {"pending", "presented", "answered", "skipped"}
    seen_seq = set()
    normalized = []
    for p in prompts:
        if not isinstance(p, dict):
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each prompt must be an object.")
        # required fields
        for k in ("sequence_no", "prompt_type", "title", "body", "is_required"):
            if k not in p:
                _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Missing required field: {k}.")
        seq = p.get("sequence_no")
        if not isinstance(seq, int) or seq < 1:
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sequence_no must be an integer >= 1.")
        if seq in seen_seq:
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Duplicate sequence_no in request payload.", sequence_no=seq)
        seen_seq.add(seq)

        pt = p.get("prompt_type")
        if pt not in allowed_prompt_types:
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid prompt_type.", allowed=sorted(allowed_prompt_types))

        title = p.get("title")
        if not isinstance(title, str) or not title.strip():
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title must be a non-empty string.")
        if len(title) > 200:
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "title exceeds maxLength=200.")

        body = p.get("body")
        if not isinstance(body, str) or not body.strip():
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body must be a non-empty string.")
        if len(body) > 4000:
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body exceeds maxLength=4000.")

        is_required = p.get("is_required")
        if not isinstance(is_required, bool):
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "is_required must be a boolean.")

        choices = p.get("choices", None)
        if choices is not None:
            if not isinstance(choices, list):
                _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "choices must be an array of strings.")
            if len(choices) > 50:
                _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "choices exceeds maxItems=50.")
            for c in choices:
                if not isinstance(c, str) or not c.strip():
                    _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Each choice must be a non-empty string.")
                if len(c) > 200:
                    _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Choice exceeds maxLength=200.")

        # Map tool prompt_type to schema prompt_type
        schema_pt = "free_text" if pt == "text" else ("confirm" if pt == "boolean" else pt)

        # Enforce schema constraint: choices required for single_choice/multi_choice
        if schema_pt in ("single_choice", "multi_choice"):
            if choices is None or len(choices) < 1:
                _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "choices is required and must be non-empty for choice prompts.")
        else:
            # For non-choice prompts, choices should be omitted or empty
            if choices is not None and len(choices) != 0:
                _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "choices must be omitted or empty for non-choice prompts.")

        pst = p.get("status", None)
        if pst is not None and pst not in allowed_statuses:
            _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid prompt status.", allowed=sorted(allowed_statuses))

        normalized.append({
            "sequence_no": seq,
            "prompt_type": schema_pt,
            "title": title,
            "body": body,
            "choices": choices if choices is not None else None,
            "is_required": is_required,
            "status": pst
        })

    # Perform upsert by sequence_no
    now = _now_iso()
    all_prompts = _load("feedback_prompts.json")
    if not isinstance(all_prompts, list):
        all_prompts = []

    existing = [p for p in all_prompts if isinstance(p, dict) and p.get("feedback_request_id") == feedback_request_id]
    by_seq = {}
    for p in existing:
        by_seq[p.get("sequence_no")] = p

    transitions = {
        "pending": {"presented", "skipped"},
        "presented": {"answered", "skipped"},
        "answered": set(),
        "skipped": set()
    }

    upserted = []
    any_change = False

    for p in sorted(normalized, key=lambda x: x["sequence_no"]):
        seq = p["sequence_no"]
        curp = by_seq.get(seq)
        if curp is None:
            # create
            init_status = "pending"
            new_status = init_status
            if p["status"] is not None:
                if p["status"] == init_status:
                    new_status = init_status
                elif p["status"] in transitions[init_status]:
                    new_status = p["status"]
                else:
                    _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "INVALID_TRANSITION")
                    return _err("INVALID_TRANSITION", "Illegal prompt status transition.", from_status=init_status, to_status=p["status"], sequence_no=seq)

            row = {
                "id": "fp_" + uuid.uuid4().hex,
                "feedback_request_id": feedback_request_id,
                "sequence_no": seq,
                "prompt_type": p["prompt_type"],
                "title": p["title"],
                "body": p["body"],
                "choices": p["choices"],
                "is_required": p["is_required"],
                "status": new_status,
                "created_at": now,
                "updated_at": now
            }
            all_prompts.append(row)
            upserted.append(row)
            any_change = True
        else:
            # update fields + optional status transition
            newp = dict(curp)
            # immutable-ish: still allow updates since tool says upsert
            for fld in ("prompt_type", "title", "body", "choices", "is_required"):
                if newp.get(fld) != p[fld]:
                    newp[fld] = p[fld]
                    any_change = True

            if p["status"] is not None and p["status"] != newp.get("status"):
                cs = newp.get("status")
                if cs not in transitions:
                    _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Prompt has invalid current status.", prompt_id=newp.get("id"), current_status=cs)
                if p["status"] not in transitions[cs]:
                    _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "INVALID_TRANSITION")
                    return _err("INVALID_TRANSITION", "Illegal prompt status transition.", from_status=cs, to_status=p["status"], prompt_id=newp.get("id"))
                newp["status"] = p["status"]
                any_change = True

            if any_change:
                newp["updated_at"] = now
            # write back in list
            for i, row in enumerate(all_prompts):
                if isinstance(row, dict) and row.get("id") == newp.get("id"):
                    all_prompts[i] = newp
                    break
            upserted.append(newp)

    if not any_change:
        _log("interactive_feedback_request_prompts_upsert", auth_token, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "No prompts were created or updated.")

    _save("feedback_prompts.json", all_prompts)
    _log("interactive_feedback_request_prompts_upsert", auth_token, "success", None)
    return {"prompts": upserted, "count": len(upserted)}

def interactive_feedback_response_record(auth_token, feedback_request_id, prompt_id, response_type, response_text=None, selected_choices=None, response_boolean=None, responded_at=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0325000" if __import__("os").path.isdir("./environment_mix/0325000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt_iso(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return ("error", _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string."))
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except ValueError:
            return ("error", _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time string."))

    def _gen_id(prefix):
        # Keep vendor-like prefix: ifp_rsp_<...>
        # Generate deterministic-ish unique id offline.
        t = _now_dt()
        ts = t.strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}_{uuid.uuid4().hex[:12]}"

    def _audit(status_s, credential=None, error_code=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started_at is not None:
            latency_ms = int((time.time() - started_at) * 1000)
        logs.append(
            {
                "id": _gen_id("ifp_rlg"),
                "endpoint": "interactive_feedback_response_record",
                "credential": credential,
                "status": status_s,
                "error_code": error_code,
                "timestamp": _now_iso(),
                "latency_ms": latency_ms,
            }
        )
        _save("request_logs.json", logs)

    def _find_credential(token):
        """
        Authenticate against a client-visible value OR id.
        Different datasets may store credentials in different files/field names.
        Return (credential_row, credential_id_or_token_for_audit) or (None, None).
        """
        if not isinstance(token, str) or not token.strip():
            return (None, None)
        tok = token.strip()

        # Common possible credential stores.
        candidate_files = [
            "credentials.json",
            "api_keys.json",
            "auth_tokens.json",
            "access_tokens.json",
            "tokens.json",
            "keys.json",
        ]
        candidate_field_sets = [
            ("token",),
            ("value",),
            ("api_key",),
            ("key",),
            ("access_token",),
            ("bearer_token",),
            ("client_token",),
            ("secret",),  # NOTE: treated as client-visible here if stored plaintext
            ("id",),
        ]

        for fn in candidate_files:
            rows = _load(fn)
            if not isinstance(rows, list):
                continue
            for r in rows:
                if not isinstance(r, dict):
                    continue
                # Skip explicitly inactive/revoked if present
                st = r.get("status")
                if isinstance(st, str) and st.lower() in ("revoked", "disabled", "inactive", "expired"):
                    continue
                # Match by id first (allowed) or by any client-visible value field.
                if r.get("id") == tok:
                    return (r, r.get("id") or tok)
                for fs in candidate_field_sets:
                    for f in fs:
                        v = r.get(f)
                        if isinstance(v, str) and v == tok:
                            return (r, r.get("id") or tok)

        # No explicit credential row found; in this service the auth_token is sometimes a project id
        # (as seen in the audit args). That is still a valid client-visible identifier: treat it as
        # an "ambient credential" as long as the referenced project exists and is active.
        projects = _load("projects.json")
        if isinstance(projects, list):
            for p in projects:
                if isinstance(p, dict) and p.get("id") == tok and p.get("status") == "active":
                    return ({"type": "project", "project_id": tok}, tok)

        return (None, None)

    started = time.time()
    credential_row, credential_for_audit = _find_credential(auth_token)

    # Validate required fields/types/enums first
    if not isinstance(auth_token, str) or not auth_token.strip():
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "auth_token is required and must be a non-empty string.")
    if not isinstance(feedback_request_id, str) or not feedback_request_id.strip():
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "feedback_request_id is required and must be a non-empty string.")
    if not isinstance(prompt_id, str) or not prompt_id.strip():
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "prompt_id is required and must be a non-empty string.")
    if response_type not in ("text", "single_choice", "multi_choice", "boolean"):
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "response_type must be one of: text, single_choice, multi_choice, boolean.")

    if response_text is not None:
        if not isinstance(response_text, str):
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_text must be a string when provided.")
        if len(response_text) > 10000:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_text must be at most 10000 characters.")
    if selected_choices is not None:
        if not isinstance(selected_choices, list):
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "selected_choices must be an array of strings when provided.")
        if len(selected_choices) > 50:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "selected_choices must contain at most 50 items.")
        for i, it in enumerate(selected_choices):
            if not isinstance(it, str) or not it:
                _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", f"selected_choices[{i}] must be a non-empty string.")
            if len(it) > 200:
                _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
                return _err("VALIDATION_ERROR", f"selected_choices[{i}] must be at most 200 characters.")
    if response_boolean is not None and not isinstance(response_boolean, bool):
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "response_boolean must be a boolean when provided.")

    parsed_responded_at = None
    if responded_at is not None:
        parsed = _parse_dt_iso(responded_at, "responded_at")
        if isinstance(parsed, tuple) and parsed and parsed[0] == "error":
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return parsed[1]
        parsed_responded_at = parsed

    # Authenticate: must find some valid credential context somewhere in store.
    if credential_row is None:
        _audit("error", None, "UNAUTHORIZED", started)
        return _err("UNAUTHORIZED", "auth_token is invalid or not recognized.")

    # Load collections
    reqs = _load("feedback_requests.json")
    prompts = _load("feedback_prompts.json")
    responses = _load("feedback_responses.json")

    if not isinstance(reqs, list):
        reqs = []
    if not isinstance(prompts, list):
        prompts = []
    if not isinstance(responses, list):
        responses = []

    # Find request and prompt; enforce foreign key integrity and ownership
    fr = next((r for r in reqs if isinstance(r, dict) and r.get("id") == feedback_request_id), None)
    if fr is None:
        _audit("error", credential_for_audit, "NOT_FOUND", started)
        return _err("NOT_FOUND", "feedback_request not found.", feedback_request_id=feedback_request_id)

    prm = next((p for p in prompts if isinstance(p, dict) and p.get("id") == prompt_id), None)
    if prm is None:
        _audit("error", credential_for_audit, "NOT_FOUND", started)
        return _err("NOT_FOUND", "prompt not found.", prompt_id=prompt_id)

    if prm.get("feedback_request_id") != feedback_request_id:
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err(
            "VALIDATION_ERROR",
            "prompt does not belong to the given feedback_request.",
            feedback_request_id=feedback_request_id,
            prompt_id=prompt_id,
        )

    # Authorization: this service's store does not define per-request ACLs.
    # A valid token should not be rejected merely because it doesn't "grant access" to a specific request.
    # If token is a project id, ensure it matches request's project_id.
    if isinstance(credential_row, dict) and credential_row.get("type") == "project":
        if fr.get("project_id") != credential_row.get("project_id"):
            _audit("error", credential_for_audit, "UNAUTHORIZED", started)
            return _err(
                "UNAUTHORIZED",
                "auth_token is scoped to a different project than this feedback_request.",
                feedback_request_id=feedback_request_id,
            )

    # Request must be in a state that can accept responses
    fr_status = fr.get("status")
    if fr_status not in ("active", "awaiting_user"):
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err(
            "VALIDATION_ERROR",
            "feedback_request is not in a state that can accept responses (must be active or awaiting_user).",
            feedback_request_id=feedback_request_id,
            status=fr_status,
        )

    # Prompt must be presentable/answerable
    prm_status = prm.get("status")
    if prm_status not in ("pending", "presented"):
        # If already answered, then response exists or was redacted; either way, refuse.
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err(
            "VALIDATION_ERROR",
            "prompt is not in a state that can accept a response (must be pending or presented).",
            prompt_id=prompt_id,
            status=prm_status,
        )

    # Uniqueness: one response per prompt
    existing = next((r for r in responses if isinstance(r, dict) and r.get("prompt_id") == prompt_id), None)
    if existing is not None:
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "prompt already has a response.", prompt_id=prompt_id, response_id=existing.get("id"))

    # Validate payload matches prompt and response_type
    prompt_type = prm.get("prompt_type")
    if prompt_type not in ("free_text", "single_choice", "multi_choice", "confirm"):
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err("VALIDATION_ERROR", "prompt_type is invalid on stored prompt.", prompt_id=prompt_id, prompt_type=prompt_type)

    # Enforce prompt_type -> allowed response_type mapping (business rule)
    expected = {
        "free_text": "text",
        "single_choice": "single_choice",
        "multi_choice": "multi_choice",
        "confirm": "boolean",
    }[prompt_type]
    if response_type != expected:
        _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
        return _err(
            "VALIDATION_ERROR",
            "response_type does not match prompt_type.",
            prompt_id=prompt_id,
            prompt_type=prompt_type,
            expected_response_type=expected,
            response_type=response_type,
        )

    # Enforce response payload requirements by response_type
    if response_type == "text":
        if not isinstance(response_text, str) or not response_text.strip():
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_text is required and must be non-empty when response_type=text.")
        # selected_choices/response_boolean must not be required; allow them to be present but ignore? Real APIs usually validate strictly.
        if selected_choices is not None:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "selected_choices must be omitted when response_type=text.")
        if response_boolean is not None:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_boolean must be omitted when response_type=text.")

    elif response_type in ("single_choice", "multi_choice"):
        if not isinstance(selected_choices, list) or len(selected_choices) < 1:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err(
                "VALIDATION_ERROR",
                "selected_choices is required and must have at least 1 item when response_type is single_choice or multi_choice.",
            )
        if response_type == "single_choice" and len(selected_choices) != 1:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "single_choice responses must select exactly one choice.")
        # Must match prompt choices (stored as list of strings)
        choices = prm.get("choices")
        if not isinstance(choices, list) or len(choices) < 1 or not all(isinstance(c, str) and c for c in choices):
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "stored prompt choices are invalid for a choice-based prompt.", prompt_id=prompt_id)
        invalid = [c for c in selected_choices if c not in choices]
        if invalid:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "selected_choices contains values not present in prompt choices.", invalid_choices=invalid)
        if response_text is not None:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_text must be omitted when response_type is single_choice or multi_choice.")
        if response_boolean is not None:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_boolean must be omitted when response_type is single_choice or multi_choice.")

    elif response_type == "boolean":
        if response_boolean is None or not isinstance(response_boolean, bool):
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_boolean is required when response_type=boolean.")
        if response_text is not None:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "response_text must be omitted when response_type=boolean.")
        if selected_choices is not None:
            _audit("error", credential_for_audit, "VALIDATION_ERROR", started)
            return _err("VALIDATION_ERROR", "selected_choices must be omitted when response_type=boolean.")

    # Create response and update prompt status with lifecycle transitions
    now = _now_dt()
    responded_dt = parsed_responded_at or now
    responded_iso = responded_dt.isoformat().replace("+00:00", "Z")
    now_iso = now.isoformat().replace("+00:00", "Z")

    # Prompt lifecycle: pending/presented -> answered allowed
    prm_old = prm.get("status")
    if prm_old not in ("pending", "presented"):
        _audit("error", credential_for_audit, "INVALID_TRANSITION", started)
        return _err("INVALID_TRANSITION", "prompt cannot transition to answered from its current status.", prompt_id=prompt_id, status=prm_old)

    # Persist mutation
    rsp = {
        "id": _gen_id("ifp_rsp"),
        "feedback_request_id": feedback_request_id,
        "prompt_id": prompt_id,
        "response_type": response_type,
        "response_text": response_text if response_type == "text" else None,
        "selected_choices": selected_choices if response_type in ("single_choice", "multi_choice") else None,
        "response_boolean": response_boolean if response_type == "boolean" else None,
        "responded_at": responded_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
        "status": "recorded",
    }

    responses.append(rsp)

    prm["status"] = "answered"
    prm["updated_at"] = now_iso

    # Also update feedback_request updated_at (common real behavior) but do not transition it here.
    fr["updated_at"] = now_iso

    _save("feedback_responses.json", responses)
    _save("feedback_prompts.json", prompts)
    _save("feedback_requests.json", reqs)

    _audit("ok", credential_for_audit, None, started)
    return {"data": rsp}
